import {app,BrowserWindow,WebContentsView} from 'electron';import {mkdtemp,writeFile} from 'node:fs/promises';import{join,resolve}from'node:path';import assert from'node:assert/strict';
import {attachPlaywrightView}from'../../packages/browser/src/playwright-view.js';import{UniversalFormSession}from'../../packages/browser/src/universal-form.js';import{READ_UNIVERSAL_FORM}from'../../packages/browser/src/universal-read.js';import{profile}from'./moka-form.js';import{openDatabaseFile,writeDocument}from'../../packages/domain/src/sqlite.js';import{createApplicationAssetsStore}from'../../packages/domain/src/application-assets.js';
const directory=await mkdtemp(resolve('.backups/moka-real-shape-'));app.setPath('userData',directory);await app.whenReady();const win=new BrowserWindow({show:false}),view=new WebContentsView({webPreferences:{sandbox:true,contextIsolation:true,nodeIntegration:false,backgroundThrottling:false,partition:'moka-real-shape-fictional'}});win.contentView.addChildView(view);view.setBounds({x:0,y:0,width:1100,height:800});
const widget=(id:string,caption:string,placeholder='')=>`<div class="field"><div>${caption}</div><div><div><label><span class="sd-Input-display-value-fixture" hidden></span><input id="${id}" placeholder="${placeholder}"></label><i class="arrow"></i><div class="dropdown" hidden><div class="items"></div><button type="button" onclick="window.unwanted++">Add full name</button></div></div></div></div>`;
const html=`<style>.field{position:relative;margin:8px;display:inline-block}.arrow::before{content:"\\e732"}.dropdown{position:absolute;background:white;z-index:3}input{min-width:140px}label:focus-within .sd-Input-display-value-fixture{display:none}</style><form onsubmit="window.submits++;return false"><fieldset><legend>教育经历</legend>${widget('school','学校名称')}${widget('major','专业名称')}<label>GPA/CGPA<input id="gpa"></label></fieldset><fieldset><legend>实习经历</legend><label>公司名称<input id="company" value="虚构研究中心"></label><div><div>起止时间 / Period</div><div class="month-range-select"><span>${widget('sy','','年 / Year')}${widget('sm','','月 / Month')}</span><span><label>至今 / Present<input id="present" type="checkbox" checked value=""></label></span></div></div></fieldset><button>提交申请</button></form><script>window.submits=0;window.unwanted=0;window.choices=0;
for(const id of ['school','major','sy','sm']){const e=document.getElementById(id),root=e.closest('.field'),menu=root.querySelector('.dropdown'),items=menu.querySelector('.items');const render=()=>{items.replaceChildren();const row=document.createElement('div');row.className='row';const zh=document.createElement('div'),en=document.createElement('div');zh.textContent=e.value;en.textContent=id==='school'?'Fictional University':id==='major'?'Artificial Intelligence':'Number';row.append(zh,en);row.onmousedown=event=>event.preventDefault();row.onclick=()=>{window.choices++;const marker=root.querySelector('.sd-Input-display-value-fixture');marker.textContent=id==='sy'||id==='sm'?e.value:e.value+' / '+en.textContent;marker.hidden=false;e.value='';menu.hidden=true;};items.append(row);menu.hidden=false;};e.oninput=render;e.onkeydown=event=>{if(event.key==='Escape')menu.hidden=true;};e.onblur=()=>{menu.hidden=true;if(root.querySelector('.sd-Input-display-value-fixture').hidden)e.value='';};}
</script>`;
try{await view.webContents.loadURL('data:text/html;charset=utf-8,'+encodeURIComponent(html));const attached=await attachPlaywrightView(view.webContents),page=attached.page;let session=new UniversalFormSession(page,profile,async()=>profile,()=>1,new AbortController().signal),checks=0;
 let x=await session.inspect();const shape:any=await page.evaluate(READ_UNIVERSAL_FORM);assert.equal(shape.fields.find((f:any)=>f.label==='学校名称').ownedSelect,true);assert.ok(shape.fields.some((f:any)=>f.label==='起止时间 / Period · 开始时间 · 年'));assert.ok(!x.fields.some(f=>f.label==='至今 / Present'));checks+=3;
 const fill=async(label:string,kind:string,record:string)=>{x=await session.inspect();const fact=session.facts.find(f=>f.kind===kind&&f.record===record)!,field=x.fields.find(f=>f.label===label&&f.candidates.includes(fact.ref));assert.ok(field,label);const result=await session.fillGroup(x.observation,[{target:field.ref,fact:fact.ref}]);assert.equal(result.verified,1,JSON.stringify(result));};
 await fill('学校名称','school','education-1');await fill('专业名称','major','education-1');await fill('起止时间 / Period · 开始时间 · 年','startDate','internship-1');await fill('起止时间 / Period · 开始时间 · 月','startDate','internship-1');checks+=4;
 assert.equal(await page.locator('.dropdown:visible').count(),0);assert.equal(await page.locator('#school').inputValue(),'');assert.equal(await page.evaluate('window.choices'),4);checks+=3;
 let final=await session.verify(true);assert.equal(final.verified,4);const question=final.remaining.find(f=>f.label==='GPA/CGPA')?.question;assert.ok(question);assert.ok(!JSON.stringify(await session.verify()).includes(question.key));checks+=3;session.close();
 // Persist through the real answer store, close/reopen it, then start a new fill session.
 let file=await openDatabaseFile({directory:join(directory,'answers')});await file.transact(db=>writeDocument(db,'profile','current',profile,new Date().toISOString()));let assets=createApplicationAssetsStore(file);let state=await assets.saveAnswer({questionPattern:question.key,answer:'3.8 / 4.0',scope:{kind:'general'},risk:'ordinary',demo:false},null);assert.equal(state.answers[0]!.confirmedRevision,null);state=await assets.confirmAnswer(state.answers[0]!.id,state.answers[0]!.revision,profile.version);await file.close();file=await openDatabaseFile({directory:join(directory,'answers')});assets=createApplicationAssetsStore(file);state=await assets.getState();assert.equal(state.answers[0]!.confirmedRevision,state.answers[0]!.revision);checks+=2;
 session=new UniversalFormSession(page,profile,async()=>profile,()=>1,new AbortController().signal,true,{answers:state.answers});x=await session.inspect();const gpa=x.fields.find(f=>f.label==='GPA/CGPA');assert.ok(gpa);assert.equal(gpa.candidates.length,1);assert.equal((await session.fillGroup(x.observation,[{target:gpa.ref,fact:gpa.candidates[0]!}])).verified,1);assert.equal(await page.locator('#gpa').inputValue(),'3.8 / 4.0');assert.ok(!JSON.stringify(await session.inspect()).includes('3.8 / 4.0'));checks+=4;
 assert.equal(await page.evaluate('window.unwanted'),0);assert.equal(await page.evaluate('window.submits'),0);checks+=2;session.close();await file.close();
 // Adding education before an already-filled internship must not rename its group.
 await page.setContent(`<form><section><h2>教育经历</h2><div><label>学校名称<input id="first-school"></label><label>专业名称<input></label></div><button type="button" onclick="const n=document.createElement('div');n.innerHTML='<label>学校名称<input id=second-school></label><label>专业名称<input></label>';this.before(n)">添加教育经历</button></section><section><h2>实习经历</h2><label>公司名称<input id="new-company"></label><label>职位名称<input id="new-role"></label></section></form>`);
 session=new UniversalFormSession(page,profile,async()=>profile,()=>1,new AbortController().signal);
 await fill('学校名称','school','education-1');await fill('公司名称','organization','internship-1');await fill('职位名称','role','internship-1');x=await session.inspect();const add=x.actions[0];assert.ok(add);await session.act({observation:x.observation,action:'add',target:add.ref});assert.equal((await session.verify()).verified,3);await fill('学校名称','school','education-2');assert.equal((await session.verify()).verified,4);checks+=3;
 session.close();
 // Real SD behavior: selecting year removes placeholders and auto-selects month
 // 1. Dates requested before school must not strand the partially written group.
 await page.setContent(`<style>.arrow::before{content:"\\e732"}.dropdown{position:absolute;background:white}label:focus-within [class*="Input-display-value-"]{display:none}</style><fieldset><legend>教育经历</legend><div><div>就读时间 / Education period</div><div class="month-range-select"><span>${widget('dynamic-year','','年 / Year')}${widget('dynamic-month','','月 / Month')}</span><span>-</span><span>${widget('other-year','','年 / Year')}${widget('other-month','','月 / Month')}</span></div></div><label>学校名称<input id="dynamic-school"></label></fieldset>`);
 await page.evaluate(()=>{for(const id of ['dynamic-year','dynamic-month']){const input=document.getElementById(id) as HTMLInputElement,root=input.closest('.field')!,menu=root.querySelector('.dropdown') as HTMLElement;
   input.oninput=()=>{const value=input.value,row=document.createElement('div');row.className='option';row.textContent=value;row.onmousedown=event=>event.preventDefault();row.onclick=()=>{const marker=root.querySelector('[class*="Input-display-value-"]') as HTMLElement;marker.textContent=value;marker.hidden=false;input.value='';input.placeholder='';menu.hidden=true;
     if(id==='dynamic-year'){const month=document.getElementById('dynamic-month') as HTMLInputElement,display=month.closest('.field')!.querySelector('[class*="Input-display-value-"]') as HTMLElement;display.textContent='1';display.hidden=false;month.placeholder='';}
   };menu.replaceChildren(row);menu.hidden=false;};input.onblur=()=>{menu.hidden=true;};input.onkeydown=event=>{if(event.key==='Escape')menu.hidden=true;};}});
 session=new UniversalFormSession(page,profile,async()=>profile,()=>1,new AbortController().signal);x=await session.inspect();
 const start=session.facts.find(f=>f.record==='education-1'&&f.kind==='startDate')!,schoolFact=session.facts.find(f=>f.record==='education-1'&&f.kind==='school')!;
 const ordered=['开始时间 · 年','开始时间 · 月'].map(label=>({target:x.fields.find(f=>f.label.endsWith(label))!.ref,fact:start.ref}));ordered.push({target:x.fields.find(f=>f.label==='学校名称')!.ref,fact:schoolFact.ref});
 const dynamicResult=await session.fillGroup(x.observation,ordered);assert.equal(dynamicResult.verified,3,JSON.stringify(dynamicResult));assert.equal((await session.verify()).verified,3);checks+=2;
 const populated:any=await page.evaluate(READ_UNIVERSAL_FORM);assert.ok(populated.fields.some((f:any)=>f.label.endsWith('开始时间 · 年')&&f.datePart==='year'));assert.ok(populated.fields.some((f:any)=>f.label.endsWith('开始时间 · 月')&&Number(f.value)===Number(start.value.slice(5,7))));checks+=2;
 await page.evaluate(()=>{const input=document.getElementById('dynamic-year') as HTMLInputElement;input.value='2025';const marker=input.closest('.field')!.querySelector('[class*="Input-display-value-"]') as HTMLElement;marker.hidden=true;});
 const queryOnly:any=await page.evaluate(READ_UNIVERSAL_FORM);assert.equal(queryOnly.fields.find((f:any)=>f.queryPending)?.datePart,undefined);checks++;
 session.close();await attached.close();const report={mokaShape:true,ok:true,checks,realEmployer:false,paidRequests:0,persistedAndReused:true,stableGroupsAfterAdd:true,dynamicDatePlaceholders:true,identityBeforeDates:true};await writeFile(join(directory,'report.json'),JSON.stringify(report));console.log(JSON.stringify(report));view.webContents.close();win.destroy();app.exit(0);
}catch(e){console.error(e);win.destroy();app.exit(1);}
